package com.paicli.state;

import java.sql.*;import java.util.*;

public final class McpSessionStore {
 private final Connection c; public McpSessionStore(Connection c){this.c=c;}
 public boolean manifestMatches(String manifestId,String serverId,String configHash,String executableContentHash)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT 1 FROM mcp_server_manifests WHERE manifest_id=? AND server_id=? AND config_hash=? AND executable_content_hash=?")){s.setString(1,manifestId);s.setString(2,serverId);s.setString(3,configHash);s.setString(4,executableContentHash);try(ResultSet r=s.executeQuery()){return r.next();}}}
 public void createSession(String id,String manifest,String server,String scope,String occurrence,int attempt)throws SQLException{if(attempt<1)throw new IllegalArgumentException("attempt >= 1");try(PreparedStatement check=c.prepareStatement("SELECT 1 FROM mcp_server_manifests WHERE manifest_id=? AND server_id=?")){check.setString(1,manifest);check.setString(2,server);try(ResultSet r=check.executeQuery()){if(!r.next())throw new IllegalArgumentException("session server does not match manifest");}}try(PreparedStatement s=c.prepareStatement("INSERT INTO mcp_sessions(session_id,manifest_id,server_id,run_scope_key,occurrence_key,attempt_number,status) VALUES(?,?,?,?,?,?,'CONFIGURED')")){s.setString(1,McpStoreSupport.id(id,"sessionId"));s.setString(2,manifest);s.setString(3,server);s.setString(4,McpStoreSupport.text(scope,"scope",512));s.setString(5,McpStoreSupport.text(occurrence,"occurrence",512));s.setInt(6,attempt);s.executeUpdate();}}
 public void markStarting(String id)throws SQLException{transition(id,"STARTING",Set.of("CONFIGURED"),null,null);}
 public void markInitializing(String id,String processIdentityHash)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE mcp_sessions SET status='INITIALIZING',process_identity_hash=? WHERE session_id=? AND status='STARTING'")){s.setString(1,McpStoreSupport.text(processIdentityHash,"process identity",128));s.setString(2,id);required(s);}}
 public void markInitializing(String id)throws SQLException{markInitializing(id,"unknown");}
 public void markReady(String id,String protocol,String infoHash,String caps)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE mcp_sessions SET status='READY',negotiated_protocol_version=?,server_info_hash=?,capability_summary_json=?,ready_at=datetime('now') WHERE session_id=? AND status='INITIALIZING'")){s.setString(1,protocol);s.setString(2,infoHash);s.setString(3,McpStoreSupport.optional(caps,4096));s.setString(4,id);required(s);}}
 public void markUnhealthy(String id,String error)throws SQLException{markUnhealthy(id,"PROTOCOL",error);}
 public void markUnhealthy(String id,String category,String error)throws SQLException{transition(id,"UNHEALTHY",Set.of("READY","INITIALIZING","STARTING"),category,error);}
 public void markFailed(String id,String category,String error)throws SQLException{transition(id,"FAILED",Set.of("CONFIGURED","STARTING","INITIALIZING","READY","UNHEALTHY","SHUTTING_DOWN"),category,error);}
 public void markShuttingDown(String id)throws SQLException{transition(id,"SHUTTING_DOWN",Set.of("READY","INITIALIZING","UNHEALTHY"),null,null);}
 public void markClosed(String id,Integer exit,String stderrHash,String stderr)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE mcp_sessions SET status='CLOSED',process_exit_code=?,stderr_hash=?,bounded_stderr_excerpt=?,completed_at=datetime('now') WHERE session_id=? AND status IN ('SHUTTING_DOWN','UNHEALTHY')")){if(exit==null)s.setNull(1,Types.INTEGER);else s.setInt(1,exit);s.setString(2,stderrHash);s.setString(3,McpStoreSupport.optional(stderr,4096));s.setString(4,id);required(s);}}
 public Optional<SessionRecord> findById(String id)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM mcp_sessions WHERE session_id=?")){s.setString(1,id);try(ResultSet r=s.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
 public List<SessionRecord> findByOccurrence(String server,String scope,String occurrence)throws SQLException{return list("server_id=? AND run_scope_key=? AND occurrence_key=?",server,scope,occurrence);}
 public List<SessionRecord> findRunningResidue()throws SQLException{return list("status IN ('STARTING','INITIALIZING','READY','SHUTTING_DOWN')");}
 public boolean failResidue(String id,String expectedStatus,String category)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE mcp_sessions SET status='FAILED',error_category=?,bounded_error_excerpt=?,completed_at=datetime('now') WHERE session_id=? AND status=?")){s.setString(1,McpStoreSupport.text(category,"category",128));s.setString(2,McpStoreSupport.optional(category,4096));s.setString(3,id);s.setString(4,expectedStatus);return s.executeUpdate()==1;}}
 public boolean closeShuttingDownResidue(String id,String category)throws SQLException{try(PreparedStatement s=c.prepareStatement("UPDATE mcp_sessions SET status='CLOSED',error_category=?,bounded_error_excerpt=?,completed_at=datetime('now') WHERE session_id=? AND status='SHUTTING_DOWN'")){s.setString(1,McpStoreSupport.text(category,"category",128));s.setString(2,McpStoreSupport.optional(category,4096));s.setString(3,id);return s.executeUpdate()==1;}}
 private void transition(String id,String to,Set<String> from,String category,String error)throws SQLException{String q=String.join(",",Collections.nCopies(from.size(),"?"));try(PreparedStatement s=c.prepareStatement("UPDATE mcp_sessions SET status=?,error_category=?,bounded_error_excerpt=?,completed_at=CASE WHEN ? IN ('FAILED') THEN datetime('now') ELSE completed_at END WHERE session_id=? AND status IN ("+q+")")){int i=1;s.setString(i++,to);s.setString(i++,category);s.setString(i++,McpStoreSupport.optional(error,4096));s.setString(i++,to);s.setString(i++,id);for(String f:from)s.setString(i++,f);required(s);}}
 private List<SessionRecord> list(String where,String...p)throws SQLException{try(PreparedStatement s=c.prepareStatement("SELECT * FROM mcp_sessions WHERE "+where+" ORDER BY attempt_number")){for(int i=0;i<p.length;i++)s.setString(i+1,p[i]);List<SessionRecord>x=new ArrayList<>();try(ResultSet r=s.executeQuery()){while(r.next())x.add(map(r));}return x;}}
 private SessionRecord map(ResultSet r)throws SQLException{return new SessionRecord(r.getString("session_id"),r.getString("manifest_id"),r.getString("server_id"),r.getString("run_scope_key"),r.getString("occurrence_key"),r.getInt("attempt_number"),r.getString("status"),r.getString("negotiated_protocol_version"),r.getString("catalog_id"),r.getString("process_identity_hash"),(Integer)r.getObject("process_exit_code"),r.getString("stderr_hash"),r.getString("bounded_stderr_excerpt"),r.getString("error_category"),r.getString("bounded_error_excerpt"),r.getString("started_at"),r.getString("ready_at"),r.getString("completed_at"));}
 private static void required(PreparedStatement s)throws SQLException{if(s.executeUpdate()!=1)throw new SQLException("session not found or invalid transition");}
 public record SessionRecord(String sessionId,String manifestId,String serverId,String runScopeKey,String occurrenceKey,int attemptNumber,String status,String protocolVersion,String catalogId,String processIdentityHash,Integer processExitCode,String stderrHash,String stderrExcerpt,String errorCategory,String errorExcerpt,String startedAt,String readyAt,String completedAt){}
}
